package com.healthcare.controller;
import com.healthcare.dto.DoctorDtos.*;import com.healthcare.service.DoctorService;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/doctors") public class DoctorController {private final DoctorService service;public DoctorController(DoctorService s){service=s;}@GetMapping List<View> search(@RequestParam(required=false) String specialization){return service.search(specialization);}@PostMapping @PreAuthorize("hasRole('ADMIN')") ResponseEntity<View> create(@Valid @RequestBody Create r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}}
